// Independent integer model: no producer/planner headers or point routines.
#include "json.hpp"
#include <gmpxx.h>
#include <openssl/sha.h>
#include <array>
#include <functional>
#include <algorithm>
#include <iomanip>
#include <iostream>
#include <set>
#include <tuple>
namespace tunereplay {
using Int=mpz_class;
static void check(bool b,const char*s){if(!b)throw std::runtime_error(s);}
static std::string read(const std::string&p){std::ifstream f(p,std::ios::binary);check(bool(f),"replay file missing");std::ostringstream s;s<<f.rdbuf();return s.str();}
static std::string hash(const std::string&s){unsigned char h[32];SHA256(reinterpret_cast<const unsigned char*>(s.data()),s.size(),h);std::ostringstream o;for(auto b:h)o<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(b);return o.str();}
static Json number(uint64_t n){Json j;j.kind=Json::Number;j.value=std::to_string(n);return j;}
static Json signed_number(int n){Json j;j.kind=Json::Number;j.value=std::to_string(n);return j;}
static Json text(const std::string&s){Json j;j.kind=Json::String;j.value=s;return j;}
static Json object(std::initializer_list<std::pair<const std::string,Json>>v){Json j;j.kind=Json::Object;j.object=v;return j;}
static Int integer(const Json&j){Int v;check(mpz_set_str(v.get_mpz_t(),j.str().c_str(),10)==0,"replay decimal");return v;}
struct Curve {Int n,mu;unsigned ell;};
static std::map<std::string,Curve> curves(const std::string&directory){auto c=read_json(directory+"/published-curves.json"),m=read_json(directory+"/marked-relations.json");std::map<std::string,Curve> out;for(const auto&r:c.at("rows").array){const auto name=r.at("name").str();const Json*mark=nullptr;for(const auto&row:m.at("rows").array)if(row.at("name").str()==name){check(!mark,"duplicate replay mark");mark=&row;}check(mark,"missing replay mark");check(out.emplace(name,Curve{integer(r.at("n")),integer(mark->at("mu")),unsigned(mark->at("degree").integer())}).second,"duplicate replay curve");}check(out.size()==5,"five replay curves");return out;}
struct Cost {uint64_t d=0,a=0,n=0,steps=0;bool live=false;};
static auto key(const Cost&c){return std::make_tuple(c.d+c.a,c.n,c.d,c.steps);}
static std::vector<int> naf(Int v,unsigned w){bool sign=v<0;if(sign)v=-v;const Int original=v;Int reconstructed=0,power=1;std::vector<int> out;while(v!=0){int d=0;if(mpz_odd_p(v.get_mpz_t())){Int rem=v%(1u<<w);d=int(rem.get_si());if(d>=(1<<(w-1)))d-=1<<w;v-=d;}reconstructed+=power*d;power*=2;v/=2;out.push_back(sign?-d:d);}check(reconstructed==original,"GMP recoding identity");return out;}
struct Input {std::vector<int> columns,qdigits,rdigits;std::set<int> bank{1};Cost setup;unsigned table=0;bool residual=false,sign=false;Int centered;};
static Input input(const Curve&C,unsigned m,int offset,unsigned width){Input out;Int s=C.mu;if(2*s>C.n)s-=C.n;out.centered=s;Int rem;mpz_mod_ui(rem.get_mpz_t(),s.get_mpz_t(),m);if(2*rem>m)rem-=m;Int c=rem+Int(m)*offset,k=(s-c)/m;check(Int(m)*k+c==s,"GMP split identity");out.sign=k<0;if(out.sign){k=-k;c=-c;}auto kd=naf(k,width),cd=naf(c,2);out.residual=!cd.empty();out.columns.resize(std::max(kd.size(),cd.size()));for(size_t i=0;i<out.columns.size();++i)out.columns[i]=(i<kd.size()?kd[i]*int(m):0)+(i<cd.size()?cd[i]:0);
 std::vector<std::tuple<int,int,bool>> ops;switch(m){case 1:break;case 7:ops={{1,1,0},{2,2,0},{4,4,0},{8,1,1}};break;case 11:ops={{1,1,0},{2,2,0},{4,1,0},{5,5,0},{10,1,0}};break;case 13:ops={{1,1,0},{2,1,0},{3,3,0},{6,6,0},{12,1,0}};break;case 19:ops={{1,1,0},{2,2,0},{4,1,0},{5,5,0},{10,10,0},{20,1,1}};break;default:check(m==2||m==4||m==8||m==16||m==32,"GMP radix");for(unsigned j=1;j<m;j*=2)ops.emplace_back(int(j),int(j),false);}
 auto op=[&](int a,int b,bool sub){check(out.bank.count(a)&&out.bank.count(b),"GMP prefix dependency");int v=sub?a-b:a+b;if(out.bank.insert(v).second){if(a==b&&!sub)++out.setup.d;else{++out.setup.a;out.setup.n+=sub;}}};for(auto [a,b,sub]:ops)op(a,b,sub);out.table=kd.empty()?0:(1u<<(width-2));if(out.table>1){op(int(m),int(m),false);for(unsigned j=1;j<out.table;++j)op(int((2*j-1)*m),int(2*m),false);}out.qdigits=std::move(kd);out.rdigits=std::move(cd);return out;
}
static std::vector<int> one(const Input&i,unsigned m,size_t pos){int q=pos<i.qdigits.size()?i.qdigits[pos]*int(m):0,r=pos<i.rdigits.size()?i.rdigits[pos]:0;std::vector<int> out;if(q&&r&&(q+r==0||i.bank.count(std::abs(q+r)))){if(q+r)out.push_back(q+r);}else{if(q)out.push_back(q);if(r)out.push_back(r);}return out;}
struct Answer {Cost folded,single;uint64_t transitions=0;};
static Answer solve(const Curve&C,unsigned m,int offset,unsigned width,bool brute=false){auto in=input(C,m,offset,width);size_t length=in.columns.size();std::vector<std::vector<int>> terms(length);for(size_t p=0;p<length;++p)terms[p]=one(in,m,p);
 auto options=[&](size_t pos,const auto&offer){offer(1,terms[pos-1]);int64_t value=0;for(unsigned h=1;h<=16&&h<=pos;++h){value=2*value+in.columns[pos-h];if(h>1&&(value==0||in.bank.count(int(std::abs(value))))){std::vector<int> term;if(value)term.push_back(int(value));offer(h,term);}}};
 auto prepend=[&](Cost tail,unsigned h,const std::vector<int>&v,bool started){tail.d+=started?h:0;tail.a+=v.size()-(started||v.empty()?0:1);for(int d:v)tail.n+=d<0;++tail.steps;tail.live=tail.live||!v.empty();return tail;};
 std::vector<std::array<Cost,2>> dp(length+1);for(size_t pos=1;pos<=length;++pos)for(unsigned started=0;started<2;++started){bool found=false;Cost best;options(pos,[&](unsigned h,const std::vector<int>&v){auto candidate=prepend(dp[pos-h][started||!v.empty()],h,v,started);if(!found||key(candidate)<key(best)){found=true;best=candidate;}});dp[pos][started]=best;}
 Cost main=dp[length][0];if(brute){std::function<Cost(size_t,bool)> walk=[&](size_t pos,bool started)->Cost{if(!pos)return {};bool found=false;Cost best;options(pos,[&](unsigned h,const std::vector<int>&v){auto candidate=prepend(walk(pos-h,started||!v.empty()),h,v,started);if(!found||key(candidate)<key(best)){found=true;best=candidate;}});return best;};check(key(walk(length,false))==key(main),"GMP exhaustive minimum control");}
 Cost single;bool started=false;for(size_t pos=length;pos;--pos){if(started)++single.d;for(int d:terms[pos-1]){single.n+=d<0;if(started)++single.a;else started=true;}}single.live=started;
 uint64_t transitions=0;std::vector<std::array<bool,2>> reachable(length+1);reachable[0][0]=true;int bound=*in.bank.rbegin()+1;for(size_t used=0;used<length;++used)for(unsigned live=0;live<2;++live)if(reachable[used][live]){++transitions;reachable[used+1][live||!terms[length-used-1].empty()]=true;int64_t block=0;for(unsigned h=1;h<=16&&used+h<=length;++h){block=2*block+in.columns[length-used-h];if(h>1&&(block==0||in.bank.count(int(std::abs(block))))){++transitions;reachable[used+h][live||block!=0]=true;}if(std::abs(block)>bound)break;}}
 auto total=[&](Cost v){v.d+=in.setup.d;v.a+=in.setup.a;v.n+=in.setup.n+uint64_t(in.sign&&v.live);return v;};return {total(main),total(single),transitions};
}
static std::vector<std::string> split(const std::string&s){std::istringstream stream(s);std::vector<std::string> out;std::string x;while(std::getline(stream,x,','))out.push_back(x);return out;}
static int64_t decimal(const std::string&s){check(!s.empty(),"CSV integer");size_t used=0;auto v=std::stoll(s,&used);check(used==s.size()&&v>=-64&&v<=100000000,"CSV bounded integer");return v;}
struct Row {std::string curve,arm;unsigned m,w;int offset;Cost block,single;uint64_t table,bank,normal,transitions;};
static auto rank(const Row&r,unsigned weight,bool single=false){const auto&c=single?r.single:r.block;return std::make_tuple(c.d+weight*c.a,c.n,c.d,c.a,r.table,r.m,std::abs(r.offset),r.offset,r.w);}
static Json row_json(const Row&r,bool single=false){const auto&c=single?r.single:r.block;return object({{"radix",number(r.m)},{"window",number(r.w)},{"offset",signed_number(r.offset)},{"doubles",number(c.d)},{"adds",number(c.a)},{"negations",number(c.n)},{"table_entries",number(r.table)},{"bank_points",number(r.bank)},{"normalized_entries",number(r.normal)},{"planner_transitions",single?Json{}:number(r.transitions)}});}
static void replay(const std::string&directory,const std::string&protocol,const std::string&run){auto p=read_json(protocol),body=p;body.object.erase("freeze");auto digest=p.at("freeze").at("protocol_sha256").str();check(p.at("protocol_id").str()=="CM-BLOCK-PLAN-CENSUS-V1"&&p.at("freeze").at("status").str()=="frozen"&&hash(canonical_json(body))==digest,"replay protocol binding");auto place=p.at("execution").at("placement");check(hash(read("/proc/self/exe"))==place.at("replay_binary_sha256").str(),"replay binary binding");for(const auto&list:{"input_files","source_files"})for(const auto&f:place.at(list).array)check(hash(read(f.at("path").str()))==f.at("sha256").str(),"replay file binding");auto receipt=read_json(run+"/producer.json"),raw=read(run+"/scan.csv");check(receipt.at("rows").integer()==27090&&receipt.at("protocol_sha256").str()==digest&&receipt.at("scan_sha256").str()==hash(raw),"replay producer/raw binding");auto fixture=curves(directory);std::istringstream stream(raw);std::string line;check(bool(std::getline(stream,line))&&line=="curve,arm,radix,offset,width,doubles,adds,negations,table_entries,bank_points,normalized_entries,transitions,single_doubles,single_adds,single_negations,steps","CSV header");std::set<std::tuple<std::string,unsigned,int,unsigned>> seen;std::map<std::tuple<std::string,std::string,unsigned,bool>,Row> minima;uint64_t rows=0;
 while(std::getline(stream,line)){auto v=split(line);check(v.size()==16&&fixture.count(v[0]),"CSV row shape");std::array<int64_t,14> n{};for(unsigned j=0;j<14;++j)n[j]=decimal(v[j+2]);const auto&C=fixture.at(v[0]);auto m=unsigned(n[0]),w=unsigned(n[2]);int offset=int(n[1]);check(n[0]>0&&n[2]>=2&&n[2]<=7&&offset>=-64&&offset<=64&&(m==C.ell||m==1||m==2||m==4||m==8||m==16||m==32)&&v[1]==(m==C.ell?"relation":"binary")&&seen.emplace(v[0],m,offset,w).second,"CSV finite unique design");for(unsigned j=3;j<14;++j)check(n[j]>=0,"CSV nonnegative counters");auto expected=solve(C,m,offset,w),in=input(C,m,offset,w);uint64_t table=uint64_t(m>1)+in.table+uint64_t(in.residual);check(expected.folded.d==uint64_t(n[3])&&expected.folded.a==uint64_t(n[4])&&expected.folded.n==uint64_t(n[5])&&table==uint64_t(n[6])&&in.bank.size()==uint64_t(n[7])&&(in.table>1?in.table:0)==uint64_t(n[8])&&expected.transitions==uint64_t(n[9])&&expected.single.d==uint64_t(n[10])&&expected.single.a==uint64_t(n[11])&&expected.single.n==uint64_t(n[12])&&expected.folded.steps==uint64_t(n[13]),"independent GMP full row mismatch");Row row{v[0],v[1],m,w,offset,expected.folded,expected.single,table,in.bank.size(),in.table>1?in.table:0,expected.transitions};for(unsigned weight=1;weight<=4;++weight)for(bool single:{false,true}){auto id=std::make_tuple(row.curve,row.arm,weight,single);auto it=minima.find(id);if(it==minima.end()||rank(row,weight,single)<rank(it->second,weight,single))minima.insert_or_assign(id,row);}++rows;
 }check(rows==27090&&seen.size()==27090&&minima.size()==80,"replay complete census");Json result;result.kind=Json::Array;auto old=read_json("research/cm-marked-scalar/residual-v1/plans.json");for(const auto&[name,C]:fixture)for(unsigned weight=1;weight<=4;++weight){const Json*reference=nullptr;for(const auto&r:old.at("plans").array)if(r.at("curve").str()==name&&r.at("addition_weight").integer()==int(weight))reference=&r;check(reference,"fixed direct reference");result.array.push_back(object({{"curve",text(name)},{"addition_weight",number(weight)},{"relation",row_json(minima.at({name,"relation",weight,false}))},{"binary",row_json(minima.at({name,"binary",weight,false}))},{"single_relation",row_json(minima.at({name,"relation",weight,true}),true)},{"single_binary",row_json(minima.at({name,"binary",weight,true}),true)},{"prior_direct",reference->at("direct")},{"prior_binary",reference->at("binary_control")}}));(void)C;}auto output=object({{"schema",text("cm-block-plan-census/v1")},{"rows",number(rows)},{"minimum_sets",number(minima.size())},{"protocol_sha256",text(digest)},{"scan_sha256",text(hash(raw))},{"plans",result}});std::cout<<canonical_json(output)<<'\n';
}
static void selftest(){unsigned cases=0;for(unsigned m:{1u,7u,13u})for(unsigned w:{2u,4u})for(int offset:{-1,0,1})for(int mu:{0,1,17,129,256}){Curve c{Int(257),Int(mu),13};auto answer=solve(c,m,offset,w,true);check(answer.folded.d+answer.folded.a<=answer.single.d+answer.single.a,"GMP original bound control");++cases;}std::cout<<"{\"independent_small_exhaustive_cases\":"<<cases<<",\"timing_performed\":false}\n";}
}
int main(int argc,char**argv){try{if(argc==2&&std::string(argv[1])=="--self-test"){tunereplay::selftest();return 0;}if(argc==5&&std::string(argv[1])=="--replay"){tunereplay::replay(argv[2],argv[3],argv[4]);return 0;}throw std::runtime_error("block-tune-replay --self-test | --replay FIXTURES PROTOCOL RUN");}catch(const std::exception&e){std::cerr<<"block tuning replay refused: "<<e.what()<<'\n';return 1;}}
